const input = $input.first().json || {};

function fail({ code, message, details = [], inputSnapshot = {} }) {
  return [
    {
      json: {
        stop_before_http: true,
        success: false,
        component_id: "C2-K",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        ai_result: {
          provider: input.config?.provider || null,
          model: input.config?.model || null,
          task_type: input.config?.task_type || null,
          status: "failed",
          content: null,
          parsed_json: null,
          usage: null
        },
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log",
        input_snapshot: inputSnapshot
      }
    }
  ];
}

function compactJson(value) {
  try {
    return JSON.stringify(value, null, 2);
  } catch (error) {
    return String(value);
  }
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty.",
    inputSnapshot: input
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object.",
    inputSnapshot: input
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-K will not run LLM when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ],
    inputSnapshot: input
  });
}

if (source.next_action !== "run_ai") {
  return fail({
    code: "AI_NOT_REQUESTED",
    message: "source.next_action is not run_ai.",
    details: [{ next_action: source.next_action || null }],
    inputSnapshot: input
  });
}

if (!config.provider) {
  return fail({
    code: "MISSING_PROVIDER",
    message: "config.provider is required.",
    inputSnapshot: input
  });
}

if (config.provider !== "groq") {
  return fail({
    code: "UNSUPPORTED_PROVIDER",
    message: "C2-K v1 demo supports provider = groq.",
    details: [{ provider: config.provider }],
    inputSnapshot: input
  });
}

if (!config.endpoint) {
  return fail({
    code: "MISSING_ENDPOINT",
    message: "config.endpoint is required.",
    inputSnapshot: input
  });
}

if (!config.model) {
  return fail({
    code: "MISSING_MODEL",
    message: "config.model is required.",
    inputSnapshot: input
  });
}

if (!config.task_type) {
  return fail({
    code: "MISSING_TASK_TYPE",
    message: "config.task_type is required.",
    inputSnapshot: input
  });
}

const systemInstruction = config.system_instruction || "Return concise valid JSON only.";
const userInstruction = config.user_instruction || "Analyze the payload and return a concise result.";

const userContent = [
  userInstruction,
  "",
  "Event context:",
  compactJson({
    event_id: source.event_id || null,
    event_type: source.event_type || null,
    payload: source.payload || {},
    metadata: source.metadata || {}
  }),
  "",
  "Return JSON only. Do not include markdown fences."
].join("\n");

const body = {
  model: config.model,
  messages: [
    {
      role: "system",
      content: systemInstruction
    },
    {
      role: "user",
      content: userContent
    }
  ],
  temperature: config.temperature ?? 0.2,
  max_tokens: config.max_tokens ?? 600
};

if (config.response_format === "json_object") {
  body.response_format = { type: "json_object" };
}

return [
  {
    json: {
      stop_before_http: false,
      request: {
        provider: config.provider,
        endpoint: config.endpoint,
        body
      },
      context: {
        component_id: "C2-K",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        ai_result: {
          provider: config.provider,
          model: config.model,
          task_type: config.task_type,
          status: "prepared",
          content: null,
          parsed_json: null,
          usage: null
        },
        source_result: source,
        next_action: config.default_next_action || "route_ai_result"
      }
    }
  }
];

const llmOutput = $input.first().json || {};
const prepared = $("Prepare LLM Request").first().json;
const context = prepared.context;

const content =
  llmOutput.choices?.[0]?.message?.content ??
  llmOutput.choices?.[0]?.text ??
  null;

let parsedJson = null;
let parseError = null;

if (content) {
  try {
    parsedJson = JSON.parse(content);
  } catch (error) {
    parseError = error.message;
  }
}

return [
  {
    json: {
      success: true,
      component_id: context.component_id,
      component_version: context.component_version,
      event_id: context.event_id,
      event_type: context.event_type,
      ai_result: {
        ...context.ai_result,
        status: parseError ? "completed_unparsed" : "completed",
        content,
        parsed_json: parsedJson,
        usage: llmOutput.usage || null,
        finish_reason: llmOutput.choices?.[0]?.finish_reason || null
      },
      source_result: context.source_result,
      error: parseError
        ? {
            code: "AI_RESPONSE_PARSE_WARNING",
            message: "LLM response was returned but could not be parsed as JSON.",
            details: [{ parse_error: parseError }]
          }
        : null,
      next_action: context.next_action
    }
  }
];

const prepared = $input.first().json || {};

return [
  {
    json: {
      success: prepared.success,
      component_id: prepared.component_id,
      component_version: prepared.component_version,
      event_id: prepared.event_id,
      event_type: prepared.event_type,
      ai_result: prepared.ai_result,
      source_result: prepared.source_result,
      error: prepared.error,
      next_action: prepared.next_action
    }
  }
];
